-- Repair the legacy 半帝=12 / 斗帝=13 configuration for the current 斗帝=12 rules.
-- Back up first. Run only when no users have reached the affected realms.
-- Aligns realm/stage rules with the running builtin fallback; retains player data.
-- Breakthrough parameters are retained except the removed 半帝 transition.
.bail on
.timeout 10000
BEGIN IMMEDIATE;
CREATE TEMP TABLE repair_guard (ok INTEGER CHECK(ok=1));
INSERT INTO repair_guard SELECT CASE WHEN
 (SELECT count(*) FROM cultivations WHERE major_realm>=11)=0 AND
 (SELECT count(*) FROM cultivation_realm_configs WHERE deleted_at IS NULL AND major_realm=12 AND name='半帝')=1 AND
 (SELECT count(*) FROM cultivation_realm_configs WHERE deleted_at IS NULL AND major_realm=13 AND name='斗帝')=1
 THEN 1 ELSE 0 END;
UPDATE cultivation_realm_configs SET max_total_hours=22300,updated_at=CURRENT_TIMESTAMP WHERE major_realm=11 AND deleted_at IS NULL;
UPDATE cultivation_realm_configs SET name='斗帝',title_name='斗帝',min_total_hours=22300,max_total_hours=0,is_max_realm=1,updated_at=CURRENT_TIMESTAMP WHERE major_realm=12 AND deleted_at IS NULL;
UPDATE cultivation_realm_configs SET enabled=0,deleted_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE major_realm=13 AND deleted_at IS NULL;
UPDATE cultivation_minor_realm_configs SET required_hours=11500+(22300-11500)*(minor_realm-1)/9.0,updated_at=CURRENT_TIMESTAMP WHERE major_realm=11 AND deleted_at IS NULL;
UPDATE cultivation_minor_realm_configs SET name='至高境',required_hours=22300,updated_at=CURRENT_TIMESTAMP WHERE major_realm=12 AND minor_realm=1 AND deleted_at IS NULL;
UPDATE cultivation_minor_realm_configs SET enabled=0,deleted_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE (major_realm=12 AND minor_realm>1 OR major_realm=13) AND deleted_at IS NULL;
UPDATE breakthrough_configs SET pill_name='古帝源气',min_total_hours=22300,updated_at=CURRENT_TIMESTAMP WHERE from_major_realm=11 AND deleted_at IS NULL;
UPDATE breakthrough_configs SET enabled=0,deleted_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE from_major_realm=12 AND deleted_at IS NULL;
